scripts.script:
_G.Enabled = true

local game                     = game;
local GetService               = game.GetService;

-- // Services

local Players                  = GetService(game, "Players");

-- // Variables

local Player                   = Players.LocalPlayer;
local Character                = Player.Character;

-- //

while wait() and _G.Enabled == true do
    for _, PlayerPairs in next, Players:GetPlayers() do
        if PlayerPairs.Name ~= Player.Name then
            pcall(function()
                Character.Fist.Local.Attack:FireServer(1, "Head", PlayerPairs.Character.Humanoid)
            end)
        end
    end
end
